.ds-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 10px 14px; min-height: 39px; border: 1px solid #3a4b40; border-radius: 7px; background: #202c25; color: #e7eee9; font: 550 12px/1.3 "Inter Variable", Inter, sans-serif; cursor: pointer; white-space: nowrap; transition: background 0.15s, border-color 0.15s; }
.ds-button:hover:not(:disabled) { background: #2b3a30; border-color: #617966; }
.ds-button:focus-visible { outline: 2px solid var(--accent, #a5d4aa); outline-offset: 3px; }
.ds-button:disabled { cursor: not-allowed; opacity: 0.45; }
@media (prefers-reduced-motion: reduce) { .ds-button { transition-duration: 0.01ms; } }
.ds-button.ds-primary { background: var(--accent, #a5d4aa); color: #14271b; border-color: var(--accent, #a5d4aa); }
.ds-button.ds-primary:hover:not(:disabled) { background: #bde2c1; border-color: #bde2c1; }
.ds-button.ds-primary:disabled { background: #202c25; color: #acbdb1; border-color: #3a4b40; }

