.ds-login-label { display: flex; flex-direction: column; gap: 8px; color: #c5d3ca; font: 12px "Inter Variable", Inter, sans-serif; }
.ds-login-field { box-sizing: border-box; width: 100%; min-width: 0; padding: 11px 12px; border: 1px solid #667c6d; border-radius: 6px; background: #111b15; color: #e9eeeb; caret-color: #b2dfbc; font: inherit; }
.ds-login-field:focus-visible { outline: 2px solid var(--accent, #a5d4aa); outline-offset: 3px; }

.ds-nav-item { display: flex; align-items: center; gap: 12px; padding: 12px; border: 0; border-radius: 7px; background: #293d2e; color: #d6eadd; font: 12px "Inter Variable", Inter, sans-serif; text-align: left; cursor: pointer; }
.ds-nav-item svg { color: var(--accent, #a5d4aa); }
.ds-nav-item:focus-visible { outline: 2px solid var(--accent, #a5d4aa); outline-offset: 3px; }

.ds-status-set { display: flex; flex-wrap: wrap; gap: 12px; }
.ds-status { display: inline-flex; align-items: center; gap: 6px; color: #afbeb4; font: 500 12px "Inter Variable", Inter, sans-serif; white-space: nowrap; }
.ds-status::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; flex-shrink: 0; }
.ds-online { color: var(--accent, #a5d4aa); }
.ds-offline { color: var(--muted, #a2b2a8); }
.ds-transition { color: var(--amber, #e7c089); }
.ds-error { color: var(--red, #f1a5a0); }

