.ds-card { padding: 24px; border: 1px solid var(--border, #2c3932); border-radius: var(--radius, 12px); background: var(--surface, #171f1b); color: #e9eeeb; font: 12px "Inter Variable", Inter, sans-serif; overflow: hidden; }
.ds-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }
.ds-card-head > div > span, .ds-card-metrics span { color: var(--muted, #a2b2a8); }
.ds-card-head h2 { margin: 8px 0 0; font-size: 18px; font-weight: 570; letter-spacing: -0.015em; overflow-wrap: anywhere; }
.ds-card-head .ds-status { margin-top: 3px; }
.ds-card-metrics { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 15px; padding: 25px 0; margin-bottom: 20px; border-bottom: 1px solid var(--border, #2c3932); }
.ds-card-metrics > div { display: flex; flex-direction: column; gap: 10px; }
.ds-card-metrics strong { font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; }
.ds-actions { display: flex; align-items: center; gap: 8px; }
.ds-actions .ds-button { min-height: 36px; padding: 9px 12px; font-size: 11px; }
@media (max-width: 760px) { .ds-card { padding: 21px; } .ds-card-metrics { gap: 12px; } .ds-card-metrics strong { font-size: 14px; } .ds-actions { justify-content: space-between; } .ds-actions .ds-button { flex: 1; padding: 10px; min-height: 44px; } }

.ds-terminal { background: #0d1510; padding: 15px 14px; overflow: auto; overscroll-behavior: contain; font: 13px/1.7 ui-monospace, SFMono-Regular, Consolas, monospace; }
.ds-log-line { display: grid; grid-template-columns: 65px 53px minmax(0, 1fr); gap: 9px; padding: 3px 0; align-items: start; }
.ds-log-line time { color: #97ada0; font-size: 11px; }
.ds-log-stream { color: #a4bdae; font-size: 11px; }
.ds-log-line code { color: #d1dfd5; font: inherit; white-space: pre-wrap; overflow-wrap: anywhere; }
.ds-log-system code { color: #adceb7; }
@media (max-width: 760px) { .ds-terminal { padding: 10px; } .ds-log-line { grid-template-columns: 56px minmax(0, 1fr); gap: 6px; font-size: 12px; } .ds-log-stream { display: none; } }
